mapper.select:
select
from issue_changes c where c.issue_key in
#{key,jdbcType=VARCHAR}

select

from issue_changes c
where c.kee=#{key,jdbcType=VARCHAR}

select

from issue_changes c
where c.change_type=#{changeType,jdbcType=VARCHAR} and c.kee=#{key,jdbcType=VARCHAR}

select
  c.change_data as changeData,
  coalesce(c.issue_change_creation_date, c.created_at) as changedAt,
  c.user_login as userLogin
from issue_changes c
inner join issues i on i.kee = c.issue_key and i.issue_type <> 4
inner join project_branches pb on pb.uuid = c.project_uuid and pb.is_main = ${_true}
inner join projects p on p.uuid = pb.project_uuid
where
  p.organization_uuid = #{organizationUuid,jdbcType=VARCHAR}
  and c.change_type = 'diff'
  and c.created_at >= #{minCreatedAt,jdbcType=BIGINT}
  and coalesce(c.issue_change_creation_date, c.created_at) >= #{fromDate,jdbcType=BIGINT}
  and coalesce(c.issue_change_creation_date, c.created_at) < #{toDate,jdbcType=BIGINT}
  and c.change_data like '%resolution=%'
